import json
import os

from ament_index_python.packages import get_package_prefix
from launch import LaunchDescription
from launch.actions import DeclareLaunchArgument, OpaqueFunction
from launch.substitutions import LaunchConfiguration
from launch_ros.actions import Node

# Mach-E gain tables + vehicle params, regenerated by
# .claude/skills/preview-gain-calibration/scripts/update_from_drive.py after each calibration drive.
GAIN_DIR = os.path.join(os.environ["HOME"], "autoware/src/mcity/preview_control/data/gain/mache")


def launch_setup(context):
    variant = LaunchConfiguration("gain_variant").perform(context)
    if variant not in ("withdelay", "withoutdelay"):
        raise RuntimeError(f"gain_variant must be withdelay or withoutdelay, got {variant!r}")
    with open(os.path.join(GAIN_DIR, "params.json")) as f:
        steering_ratio = float(json.load(f)["steering_ratio"])

    return [
        Node(
            package="preview_control",
            namespace="/mcity",
            executable="preview_control",
            # ~/mcity_demos installs another libpreview_control_component.so that comes first on
            # LD_LIBRARY_PATH; load this package's build instead
            additional_env={"LD_LIBRARY_PATH": os.pathsep.join(
                [os.path.join(get_package_prefix("preview_control"), "lib"), os.environ.get("LD_LIBRARY_PATH", "")])},
            parameters=[
                {"gain_folder": os.path.join(GAIN_DIR, variant) + "/"},
                # withdelay tables need the delay buffer + measured steering feedback
                {"consider_delay_lag": variant == "withdelay"},
                {"steering_ratio": steering_ratio},
                {"slope_folder": LaunchConfiguration("slope_file").perform(context)},
                {"max_ey": 1.5},
                {"max_ephi": 1.0},
                {"max_curvature": 0.2},
                # speed: cap the planned speed, gentle PI, coast (regen) before braking, pedal rise limits
                {"max_speed": 6.0},             # m/s (~13 mph); route plans up to 8.33
                {"speed_ctrl_kp": 1.0},         # was 1.8 (MKZ)
                {"speed_ctrl_ki": 0.3},         # was 0.6
                {"coast_band": 0.6},            # m/s^2 of decel handled by lift-off before any brake
                {"throttle_rate": 0.15},        # 1/s max throttle rise (2026-11-20: 0.3 -> 0.15, "sudden throttle")
                {"throttle_fall_rate": 0.3},    # 1/s max throttle drop while no brake is wanted (was immediate)
                {"brake_rate": 0.5},            # 1/s max brake rise (estop not limited)
                # MachE brake cmd 0..1 = 0..100 %: brake = brake_gain * decel [m/s^2] (MKZ table started at 18 %)
                {"brake_gain": 0.05},
                # MachE lift-off regen decel. Below the throttle table's 0.15 minimum, blend throttle to 0
                # over this decel range instead of cutting it (2026-11-20 drive: 0.15 -> 0 cuts every 2.4 s
                # at ~6 m/s = surge/regen "braking"). Measured -0.27..-0.48 m/s^2 at 3-7 m/s; provisional.
                {"lift_decel": 0.35},
                # clear the speed PI integral while by-wire is off (driver driving), so engage doesn't surge
                {"reset_when_dbw_off": True},
                # slow for turns: v <= sqrt(curve_lat_acc / curvature) (12 m radius -> 2.7 m/s, 20 m -> 3.5),
                # reached at curve_decel before the turn, never below curve_min_speed; curve_lat_acc 0 = off
                # 2026-11-20: 1.0 -> 0.6 / 0.8 -> 0.6 / 2.5 -> 2.0 ("slow down when steering")
                {"curve_lat_acc": 0.6},         # m/s^2; Nov 2 drives took turns at up to 1.8
                {"curve_decel": 0.6},           # m/s^2, within coast_band (regen), starts slowing earlier
                {"curve_min_speed": 2.0},       # m/s
                # use the lowest curve limit within the next 1.5 s: the speed loop lags ~1.5 s, and without this
                # the car entered 9-11 m bends at ~4 m/s (1.5 m/s^2) instead of 2.6 (2026-11-20 12:51 drive)
                {"curve_lookahead": 1.5},       # s
                # steering: max steering-wheel rate, rad/s (~115 deg/s); 0 = off. 2026-11-20: 3.0 -> 2.0
                {"steer_rate_limit": 2.5},      # 2026-11-20: 2.0 was too slow for the sharp turns (path-departure stop)
                # faster wheel at low speed only: 4-9 m corners at ~2 m/s need ~240 deg/s and ran ~0.9 m wide at
                # 143 deg/s (13:08 drive). 3.6 rad/s = 206 deg/s, the manual baseline's peak. Blended 2.5 -> 4.5 m/s.
                {"steer_rate_limit_low": 3.6},
                {"steer_rate_v_low": 2.5},      # m/s
                {"steer_rate_v_high": 4.5},     # m/s
                # low-pass on the steering command [s] so it ramps instead of jumping; 0 = off.
                # Must match params.json tau = actuator 0.094 + this (gain tables are designed with it).
                {"steer_filter_tau": 0.20},
                # curvature preview (feedforward) from the path, scaled by this; 0 = off (feedback only, turns late).
                # Starts steering before a turn instead of reacting after ey builds up. 2026-11-20: enabled.
                # 1.0 cut every curve ~0.4 m to the inside (clean-INS drive 12:51); 0.75 = centre it.
                {"feedforward_gain": 0.75},
                # pose heading bias: first MachE drive showed a steady -0.035 rad ephi on straights
                {"heading_offset": -0.03},
                {"heading_lookahead_points": 10},
                {"lateral_offset": 0.0},
                # path resampled every 0.04 s of travel = the gain tables' time step
                {"preview_time": 5.0},
                {"desired_time_resolution": 0.04},
                {"trajectory_abort_size": 20},
                {"trajectory_loose_abort_size": 20},
            ],
        ),
    ]


def generate_launch_description():
    return LaunchDescription(
        [
            DeclareLaunchArgument("gain_variant", default_value="withdelay",
                                  description="withdelay | withoutdelay (data/gain/mache/<variant>/)"),
            DeclareLaunchArgument("slope_file", default_value="",
                                  description="road-grade map, e.g. .../data/slope/DIT.txt; empty = flat"),
            OpaqueFunction(function=launch_setup),
        ]
    )
